import { useLayoutEffect, type RefObject } from "react";

/** How far a greeting may shrink before legibility matters more than fitting. */
const MIN_SCALE = 0.92;
const STEPS = 6;

/**
 * Shrinks a greeting until it fits the page it was given.
 *
 * A page is a fixed box, so a wish a few sentences longer than the rest used to
 * run off the bottom and get clipped. Scrolling is the wrong answer inside a
 * book, and refusing long greetings is worse, so the text scales down instead —
 * only ever downwards, and never past `MIN_SCALE`, below which the CSS scroll
 * fallback takes over.
 *
 * The scale is written to a `--ae-fit` custom property rather than held in
 * state: the element's `font-size` is a `calc()` that already references it, so
 * measuring never costs a render and React never fights the value, since it
 * does not manage custom properties it was not given.
 */
export function useFitText(
  bodyRef: RefObject<HTMLElement | null>,
  enabled: boolean,
  deps: readonly unknown[],
): void {
  useLayoutEffect(() => {
    const body = bodyRef.current;
    if (!body) return;

    // Only layouts that give a page a fixed box can clip it. Where the page
    // grows with its content, measuring would chase a height that moves with
    // every adjustment, so the greeting is simply left at its chosen size.
    if (!enabled) {
      body.style.removeProperty("--ae-fit");
      return;
    }

    let frame = 0;
    let cancelled = false;

    const availableHeight = (container: HTMLElement): number => {
      const style = getComputedStyle(container);
      const media = container.querySelector<HTMLElement>(".ae-page__media");
      const gap = media ? parseFloat(style.rowGap) || 0 : 0;
      return (
        container.clientHeight -
        (parseFloat(style.paddingTop) || 0) -
        (parseFloat(style.paddingBottom) || 0) -
        (media?.offsetHeight ?? 0) -
        gap
      );
    };

    const measure = () => {
      const container = body.parentElement;
      if (!container) return;

      // The page's scroll fallback would otherwise show and hide a scrollbar as
      // the trial sizes cross the overflow threshold, narrowing the column and
      // making the same scale measure differently depending on which side it
      // was approached from. Suppressing it keeps every trial comparable.
      const restore = container.style.overflowY;
      container.style.overflowY = "hidden";

      try {
        const available = availableHeight(container);
        // A page the book has not laid out yet has no height to fit into; the
        // observer will call back once it does.
        if (available <= 0) return;

        const fitsAt = (scale: number): boolean => {
          body.style.setProperty("--ae-fit", String(scale));
          return body.scrollHeight <= available;
        };

        if (fitsAt(1) || !fitsAt(MIN_SCALE)) return;

        let tooSmall = MIN_SCALE;
        let tooBig = 1;
        for (let step = 0; step < STEPS; step += 1) {
          const middle = (tooSmall + tooBig) / 2;
          if (fitsAt(middle)) tooSmall = middle;
          else tooBig = middle;
        }
        fitsAt(tooSmall);
      } finally {
        container.style.overflowY = restore;
      }
    };

    const schedule = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => {
        if (!cancelled) measure();
      });
    };

    schedule();

    // Hebrew webfonts land after first paint and change the metrics under us.
    document.fonts?.ready.then(() => {
      if (!cancelled) schedule();
    });

    const observer = new ResizeObserver(schedule);
    if (body.parentElement) observer.observe(body.parentElement);

    return () => {
      cancelled = true;
      cancelAnimationFrame(frame);
      observer.disconnect();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [enabled, ...deps]);
}
